use crate::error::Error;

/// Coordinate origin, independent of navigation state.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, strum::FromRepr)]
#[non_exhaustive]
#[repr(u8)]
pub enum PositionProvenance {
    /// Coordinates generated by the SDK for an unmatched report.
    SdkSynthesized = 2,
    /// Caller-supplied coordinates, including measured and estimated positions.
    SourceProvided = 1,
}

impl PositionProvenance {
    pub(crate) fn from_optional_wire_code(code: u8, record: usize) -> Result<Option<Self>, Error> {
        if code == 0 {
            return Ok(None);
        }
        Self::from_repr(code)
            .map(Some)
            .ok_or(Error::InvalidNavigationTag {
                dataset: "position_provenance",
                record,
                code,
            })
    }
}

