/// Source-reported solution method. An absent field means unreported.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, strum::FromRepr)]
#[non_exhaustive]
#[repr(u8)]
pub enum SolutionMethod {
    /// A GNSS solution without differential corrections.
    Autonomous = 1,
    /// Position estimation from motion measurements.
    DeadReckoning = 5,
    /// A GNSS solution with differential corrections.
    Differential = 2,
    /// A combined solution with a measured GNSS contribution.
    Hybrid = 6,
    /// A reported method outside this vocabulary.
    Other = 7,
    /// Real-time kinematic positioning with fixed ambiguities.
    RtkFixed = 4,
    /// Real-time kinematic positioning with float ambiguities.
    RtkFloat = 3,
}

impl SolutionMethod {
    pub(crate) fn from_optional_wire_code(code: u8, record: usize) -> Result<Option<Self>, Error> {
        if code == 0 {
            return Ok(None);
        }
        Self::from_repr(code)
            .map(Some)
            .ok_or(Error::InvalidNavigationTag {
                dataset: "method",
                record,
                code,
            })
    }
}

/// Source-reported navigation state. An absent field has no state observation.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, strum::FromRepr)]
#[non_exhaustive]
#[repr(u8)]
pub enum SolutionState {
    /// An estimate without a measured GNSS contribution.
    EstimatedOnly = 3,
    /// A solution with a measured GNSS contribution.
    Fix = 1,
    /// Navigation loss reported by the producer.
    NoFix = 2,
    /// Explicit uncertainty that blocks inferred state.
    Unknown = 4,
}

impl SolutionState {
    pub(crate) fn from_optional_wire_code(code: u8, record: usize) -> Result<Option<Self>, Error> {
        if code == 0 {
            return Ok(None);
        }
        Self::from_repr(code)
            .map(Some)
            .ok_or(Error::InvalidNavigationTag {
                dataset: "state",
                record,
                code,
            })
    }
}
